def load() -> pd.DataFrame:
    import pandas as pd

    path = "data/environment/input/boston-harbor-beaches.txt"
    with open(path, "r", encoding="utf-8", errors="replace") as f:
        lines = f.readlines()

    return pd.DataFrame({"line": [ln.rstrip("\n") for ln in lines]})

def process(loadBeachCsvs):
    import pandas as pd
